"},{"id":"C2","fichier":"src/wavedevsecops/engine/designation.py","ligne":132,"severite":"Important","description":"La recherche d’une entrée du stash compare les SHA avec `>=` au lieu de vérifier leur égalité. Ainsi, une désignation `commit:<sha>` qui ne correspond à aucun commit ni stash est acceptée dès que son SHA est lexicalement inférieur à celui d’une entrée du stash, ce qui valide une mauvaise réponse et peut désigner un élément inexistant.","test_pytest":"from types import SimpleNamespace

from wavedevsecops.engine.designation import _exists


def test_un_sha_de_commit_doit_correspondre_exactement_a_une_entree_du_stash() -> None:
    state = SimpleNamespace(commits=[], stash=[SimpleNamespace(sha="b", index=0, message="WIP")])

    assert _exists("commit:a", state) is False
